DATA=''
from pathlib import Path
import base64,zlib,json,re,struct,hashlib,datetime,subprocess,sys
raw=zlib.decompress(base64.b64decode(DATA));assert hashlib.sha256(raw).hexdigest()=='5bab614f7a7a95d7f542faefc38b940560dfb5ec70e2588cca78ed537f3036b2';D=json.loads(raw)
R=Path('/workspaces/pokefirered');P=R/'tools/hoenn_import/patches';names=['RusturfTunnel','VerdanturfTown_WandasHouse','VerdanturfTown'];before={};changed={}
def read(p,optional=False):
 p=Path(p);v=p.read_bytes() if p.exists() else None;assert optional or v is not None,str(p)+' missing';before[str(p.relative_to(R))]=v;return v.decode() if v is not None else ''
def put(p,s):changed[str(Path(p).relative_to(R))]=s.encode()
def once(s,a,b):
 assert s.count(a)==1,(a,s.count(a));return s.replace(a,b)
def digest(b):return hashlib.sha256(b).hexdigest() if b is not None else None
maps={n:json.loads(read(R/'data/maps'/n/'map.json')) for n in names}
for n in names:
 for k in ['scripts.inc','text.inc']:read(R/'data/maps'/n/k)
