ls=json.loads((R/'data/layouts/layouts.json').read_text())['layouts'];layout_hash={}
for n,points in [(names[0],[(x,y) for y in (4,5) for x in range(21,28)]),(names[1],[(7,4)])]:
 l=next(x for x in ls if x.get('id')==maps[n]['layout']);b=(R/l['blockdata_filepath']).read_bytes();layout_hash[l['blockdata_filepath']]=digest(b)
 for x,y in points:
  v=struct.unpack_from('<H',b,2*(y*l['width']+x))[0];assert ((v>>10)&3)==0 and v>>12==3,(n,x,y,hex(v))
fs=(R/'src/field_specials.c').read_text();assert re.search(r'if\s*\(IsPlayerOnMap\(MAP_RUSTURF_TUNNEL\)\)\s*SetHideFlag\(FLAG_HIDE_HOENN_WANDA_BOYFRIEND,\s*devon < 3 \|\| FlagGet\(FLAG_HOENN_RUSTURF_OPEN\)\);\s*else\s*SetHideFlag\(FLAG_HIDE_HOENN_WANDA_BOYFRIEND,\s*!FlagGet\(FLAG_HOENN_RUSTURF_OPEN\)\);',fs)
s=read(P/'RusturfTunnel.scripts.inc');assert 'FLAG_TEMP_' not in s and 'EventScript_WandaBoyfriend' not in s;assert 'FLAG_TEMP_' not in before['data/maps/RusturfTunnel/scripts.inc'].decode();s=once(s,'RusturfTunnel_OnTransition::\n\tspecial HoennZ3_SetupObjects\n\tend','RusturfTunnel_OnTransition::\n\tsetflag FLAG_TEMP_1\n\tspecial HoennZ3_SetupObjects\n\tend');put(P/'RusturfTunnel.scripts.inc',s.rstrip()+'\n'+D['tunnel'])
s=read(P/'VerdanturfTown_WandasHouse.scripts.inc');assert 'special HoennZ3_SetupObjects' in s and 'WandaWallyHere' in s;s=once(s,'VerdanturfTown_WandasHouse_EventScript_Wanda::\n\tlock\n\tfaceplayer\n','VerdanturfTown_WandasHouse_EventScript_Wanda::\n\tlock\n\tfaceplayer\n\tgoto_if_set FLAG_HOENN_RUSTURF_OPEN, VerdanturfTown_WandasHouse_EventScript_WandaReunited\n');assert 'VerdanturfTown_WandasHouse_EventScript_H0::' not in s;put(P/'VerdanturfTown_WandasHouse.scripts.inc',s.rstrip()+'\n'+D['house'])
s=read(P/'VerdanturfTown.scripts.inc',True);assert not s.strip(),'Town script patch changed; inspect instead of overwriting'
for i,kind in [(1,'NPC'),(2,'NPC'),(7,'SIGN')]:
 a='VerdanturfTown_EventScript_H%d::\n\tmsgbox VerdanturfTown_Text_H%d, MSGBOX_%s\n\tend'%(i,i,kind);assert before['data/maps/VerdanturfTown/scripts.inc'].decode().count(a)==1
put(P/'VerdanturfTown.scripts.inc',D['town'].lstrip())
for n in names:
 s=read(P/(n+'.text.inc'));assert '_Text_Reunion' not in s
 if n==names[1]:
  for label,block in D['replaceTexts'].items():
   pattern=r'^'+re.escape(label)+r'::\n(?:[ \t].*\n)+';s,c=re.subn(pattern,lambda m:block,s,flags=re.M);assert c==1,(label,c)
 put(P/(n+'.text.inc'),s.rstrip()+'\n'+D['texts'][n])
def obj(g,x,y,m,script,flag):return dict(type='object',graphics_id='OBJ_EVENT_GFX_'+g,x=x,y=y,elevation=3,movement_type='MOVEMENT_TYPE_'+m,movement_range_x=0,movement_range_y=0,trainer_type='TRAINER_TYPE_NONE',trainer_sight_or_berry_tree_id='0',script=script,flag=flag)
newobjs={names[0]:[obj('BLACK_BELT',23,5,'FACE_LEFT','RusturfTunnel_EventScript_WandaBoyfriend','FLAG_HIDE_HOENN_WANDA_BOYFRIEND'),obj('WOMAN_2',26,5,'FACE_LEFT','RusturfTunnel_EventScript_ReunionWanda','FLAG_TEMP_1')],names[1]:[obj('BLACK_BELT',7,4,'FACE_LEFT','VerdanturfTown_WandasHouse_EventScript_WandaBoyfriend','FLAG_HIDE_HOENN_WANDA_BOYFRIEND')]}
for n,items in newobjs.items():
 p=P/(n+'.json');data=json.loads(read(p));assert not any('WandaBoyfriend' in o.get('script','') for o in data.get('object_events',[]));data.setdefault('object_events',[]).extend(items);put(p,json.dumps(data,indent=2,ensure_ascii=False)+'\n')
for p,b in changed.items():
 if p.endswith('scripts.inc') or p.endswith('text.inc'):
  labels=re.findall(r'^(\w+)::',b.decode(),re.M);assert len(labels)==len(set(labels)),p+' duplicate labels'
report={'task':'Rusturf Wanda reunion E10','scope':names,'before':{p:digest(v) for p,v in before.items()},'planned':{p:digest(v) for p,v in changed.items()},'layout_hash':layout_hash,'player_movement':'unchanged','save_layout':'unchanged','new_story_flags':0,'build_and_runtime':'pending'}
if '--apply' not in sys.argv:print(json.dumps(report,indent=2));print('CHECK PASS; pass --apply to write');sys.exit(0)
out=R/'outputs/rusturf-wanda-reunion-v1'/datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ');out.mkdir(parents=True,exist_ok=False)
for p,b in before.items():
 if b is not None:
  q=out/'backup'/p;q.parent.mkdir(parents=True,exist_ok=True);q.write_bytes(b)
for p,b in changed.items():(R/p).write_bytes(b)
subprocess.run([sys.executable,str(R/'tools/hoenn_import/apply_patches.py'),*names],cwd=R,check=True)
for n in names:
 for k in ['scripts.inc','text.inc']:
  labels=re.findall(r'^(\w+)::',(R/'data/maps'/n/k).read_text(),re.M);assert len(labels)==len(set(labels)),(n,k,'duplicate label')
m=json.loads((R/'data/maps/RusturfTunnel/map.json').read_text());assert len(m['object_events'])==7 and m['object_events'][-2:]==newobjs[names[0]];assert m['object_events'][:5]==maps[names[0]]['object_events'];h=json.loads((R/'data/maps/VerdanturfTown_WandasHouse/map.json').read_text());assert len(h['object_events'])==4 and h['object_events'][-1]==newobjs[names[1]][0];assert h['object_events'][:3]==maps[names[1]]['object_events']
for p,v in layout_hash.items():assert digest((R/p).read_bytes())==v
report['after']={p:digest((R/p).read_bytes()) for p in before};report['status']='source applied; build and native-event QA pending';(out/'manifest.json').write_text(json.dumps(report,indent=2)+'\n');print('APPLIED',out/'manifest.json')
